Object.assign(nervousQuestionHints, {"13feb955-78dd-517b-b546-d2109dcccf87": "La corriente describe movimiento de cargas.", "ee3f5533-691c-59fc-8c9b-bae4ab19f460": "Compara la carga interior con la exterior.", "662f2b63-8e62-5aad-9b6c-23c379374bb2": "Recuerda la relación 3:2 y el sodio hacia fuera.", "2c13905e-e279-5f63-9e8c-46495150c5ca": "Las cargas de signo contrario se atraen.", "46edae80-8fa8-5be9-ae5d-dad15609a8d8": "Graduado significa que la respuesta puede ser menor o mayor.", "22b56a51-e1c6-5345-ac69-a2fbe6b5e464": "Busca el término que indica disminución.", "93a510a0-4257-5994-b1ec-1a7ebec5828b": "El umbral es el mínimo necesario para disparar.", "881cd4b9-0e76-53d3-b63c-9e78a16c8ec3": "Repasa qué canales se abren para que el interior vuelva a ser negativo.", "26db9948-dc42-5d03-8f18-8eac1612efc7": "Absoluto significa que no hay excepción por aumentar la intensidad.", "117828c1-2a48-5389-8437-181bf29d1e85": "Se compara con la conducción continua de las fibras amielínicas.", "6237c5ce-bed7-529e-82ac-edbf76c2a0ff": "Las vesículas almacenan el mensajero que se libera en la sinapsis.", "ca891225-335f-56b9-abdd-681415867d0e": "En el esquema aparece como Ca²⁺.", "543a6b23-f608-55c8-b0a3-d894655b4aa2": "El nombre de esta sinapsis indica el mensajero utilizado.", "120f8156-9850-514f-98ba-d07faa7c97cb": "La comunicación necesita comenzar y terminar de forma coordinada.", "da990b70-6c3a-548f-92c6-758f2d5751ad": "Excitación significa facilitar que la neurona dispare.", "85e9a61a-c3c4-5a88-a365-c8d4761a55b3": "La clave es la misma sinapsis y la cercanía en el tiempo.", "41ef5c48-1518-51df-8701-6c8af654bb61": "La clave es que las señales llegan desde lugares distintos.", "cdd0c6d8-87a8-50db-8b5b-7a9732c5cfcf": "Se incorporan más neuronas a la respuesta.", "5361775b-8fcd-5cb0-b3fb-724cd3f5bb64": "Divergir significa ramificarse hacia varios destinos.", "1c46378b-911f-5872-9676-289d426a7cda": "Converger significa que varias entradas se reúnen."});
